'use client';
import {useEffect,useState,useRef,FormEvent} from 'react';import {ArrowUpRight,ArrowRight,CalendarDays,MapPin,Menu,X,Users,Ticket,ChevronRight,Check,Mail,Phone,Search,Plus,Download,LogOut,LayoutDashboard,Music2,BookOpen,Camera,Clock,ShieldCheck,Settings,CheckCircle2,AlertCircle,RefreshCw,Send,Minus} from 'lucide-react';
import {clubLogo,clubStory} from '@/lib/club-brand';
import {club,archive} from '@/lib/content';import type {Activity,Account,Booking,Settings as ClubSettings} from '@/lib/model';
type Pub= {activities:(Omit<Activity,'occurrences'>&{occurrences:(Activity['occurrences'][number]&{remaining:number})[]})[];content:{homeText:string;about:string;membershipText:string;address:string;phone:string;contactEmail:string;gallery:{url:string;alt:string}[];membershipFeeCents:number|null;membershipFrom:string;membershipTo:string};mode:string;onlineReady:boolean;demoAccounts:{role:string;email:string;cf:string}[]};
function uuid(){const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,n=>n.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`}
const presentation=process.env.NEXT_PUBLIC_PRESENTATION_DEMO==='true';
const paths:Record<string,string>={home:'/',events:'/calendario',about:'/chi-siamo',membership:'/tesseramento',archive:'/archivio',gallery:'/galleria',contact:'/contatti',account:'/area-personale',admin:'/gestionale',login:'/accedi'};
const eur=(n:number)=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(n/100);
const dt=(v:string,short=false)=>new Intl.DateTimeFormat('it-IT',{dateStyle:short?'medium':'full',timeStyle:short?undefined:'short',timeZone:'Europe/Rome'}).format(new Date(v));
const statusText:Record<string,string>={confirmed:'Confermata',held:'Pagamento in attesa',cancelled:'Annullata',expired:'Scaduta',waiting:'In lista',offered:'Posti riservati per te',converted:'Prenotata',withdrawn:'Ritirata',pending:'In coda',leased:'In elaborazione',accepted:'Accettato dal provider',delivered:'Consegnato',failed:'Fallito',unknown:'Da verificare',draft:'Bozza',published:'Pubblicata',concluded:'Conclusa',active:'Attiva',review:'In verifica',revoked:'Revocata'};
async function api(path:string,body?:unknown){if(presentation)return (await import('../../demo/browser-api')).demoApi(path,body);const r=await fetch('/api/'+path,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw new Error(data.error||'Operazione non riuscita');return data}
function Poster({cover='music',title,small=false}:{cover?:string;title:string;small?:boolean}){return <div className={`poster poster-${cover} ${small?'poster-small':''}`} aria-hidden="true"><div className="poster-grain"/><div className="poster-orbit"/><span className="poster-kicker">CONTEROSSO / SOCIAL CLUB</span><div className="poster-title">{title}</div><span className="poster-mark">CULTURA.<br/>DA VIVERE.</span><ArrowUpRight className="poster-arrow"/></div>}
function Empty({title,children}:{title:string;children:React.ReactNode}){return <div className="empty"><CalendarDays size={32}/><h3>{title}</h3><p>{children}</p></div>}
function Badge({children,tone=''}:{children:React.ReactNode;tone?:string}){return <span className={'badge '+tone}>{children}</span>}
function Dialog({title,children,onClose}:{title:string;children:React.ReactNode;onClose:()=>void}){const closeRef=useRef(onClose);closeRef.current=onClose;useEffect(()=>{const previous=document.activeElement as HTMLElement;const listener=(e:KeyboardEvent)=>{if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const items=Array.from(document.querySelectorAll<HTMLElement>('.dialog button:not([disabled]),.dialog input:not([disabled]),.dialog select:not([disabled]),.dialog textarea:not([disabled]),.dialog a[href]'));const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',listener);const old=document.body.style.overflow;document.body.style.overflow='hidden';const el=document.querySelector<HTMLButtonElement>('.dialog-close');el?.focus();return()=>{document.removeEventListener('keydown',listener);document.body.style.overflow=old;previous?.focus()}},[]);return <div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="dialog" role="dialog" aria-modal="true" aria-label={title}><div className="dialog-heading"><h2>{title}</h2><button className="icon-button dialog-close" aria-label="Chiudi" onClick={onClose}><X/></button></div>{children}</section></div>}
export default function ClubApp({initialView,initialEventId}:{initialView:string;initialEventId?:string}){
 const [view,setView]=useState(initialView),[eventId,setEventId]=useState(initialEventId||''),[pub,setPub]=useState<Pub|null>(null),[me,setMe]=useState<any>(null),[menu,setMenu]=useState(false),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[query,setQuery]=useState(''),[category,setCategory]=useState('Tutte'),[dateFilter,setDateFilter]=useState(''),[tab,setTab]=useState('overview'),[editor,setEditor]=useState<Activity|null|false>(false),[memberEditor,setMemberEditor]=useState<any>(null),[cancelId,setCancelId]=useState('');
 const [participants,setParticipants]=useState([{name:'',surname:'',cf:''}]),[selectedOccurrence,setSelectedOccurrence]=useState(''),[method,setMethod]=useState<'onsite'|'online'>('onsite'),[bookingStep,setBookingStep]=useState(0),[terms,setTerms]=useState(false),[bookKey,setBookKey]=useState('');
 const [login,setLogin]=useState({email:'',cf:'',register:false,name:'',surname:'',phone:'',whatsapp:false}),[challenge,setChallenge]=useState(''),[otp,setOtp]=useState(''),[totp,setTotp]=useState(''),[demoCode,setDemoCode]=useState('');
 const [importPreview,setImportPreview]=useState<any>(null),[notification,setNotification]=useState({activityId:'',message:''});
 const account:Account|undefined=me?.account;const staff=!!account&&account.role!=='user';
 async function refresh(){const [p,m]=await Promise.all([api('public'),api('me')]);setPub(p);setMe(m)}
 useEffect(()=>{refresh().catch(e=>setToast(e.message));const pop=()=>{const path=presentation?location.hash.slice(1)||'/':location.pathname;const found=Object.keys(paths).find(k=>paths[k]===path);if(path.startsWith('/attivita/')){setView('event');setEventId(path.split('/')[2])}else setView(found||'home')};if(presentation)pop();window.addEventListener('popstate',pop);return()=>window.removeEventListener('popstate',pop)},[]);
 useEffect(()=>{if(view==='event'&&!bookKey)setBookKey(uuid())},[view,eventId,bookKey]);
 useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(''),10000);return()=>clearTimeout(id)},[toast]);
 function go(next:string,id?:string){setView(next);setMenu(false);if(id)setEventId(id);const url=next==='event'?'/attivita/'+id:paths[next]||'/';if(presentation)location.hash=url;else history.pushState({},'',url);window.scrollTo({top:0,behavior:'smooth'});if(next==='event'){setBookingStep(0);setSelectedOccurrence('');setParticipants([presentation&&account?{name:account.name,surname:account.surname,cf:account.cfKey}:{name:'',surname:'',cf:''}]);setTerms(false);setBookKey(uuid())}}
 async function perform(fn:()=>Promise<any>,success='Operazione completata.'){setBusy(true);try{const r=await fn();await refresh();if(success)setToast(success);return r}catch(e){setToast((e as Error).message);return null}finally{setBusy(false)}}
 const current=pub?.activities.find(e=>e.id===eventId);const future=(pub?.activities||[]).filter(e=>e.status==='published'&&e.occurrences.some(o=>!o.cancelled&&Date.parse(o.startsAt)>Date.now()));const filtered=future.filter(e=>(category==='Tutte'||category===e.category)&&`${e.title} ${e.description}`.toLowerCase().includes(query.toLowerCase())&&(!dateFilter||e.occurrences.some(o=>o.startsAt.slice(0,10)===dateFilter)));
 const content=pub?.content;
 const aboutText=!content?.about||content.about.startsWith('Musica, parole, fotografia e occasioni per stare insieme.')?clubStory:content.about;
 const brand=<><img className="club-symbol" src={clubLogo} alt=""/><span className="brand-name">conterosso.<small>SOCIAL CLUB / MOLFETTA</small></span></>;
 function EventCard({e}:{e:Pub['activities'][number]}){const o=e.occurrences.find(o=>Date.parse(o.startsAt)>Date.now()&&!o.cancelled)||e.occurrences[0];return <button className="event-card" onClick={()=>go('event',e.id)}><Poster cover={e.cover} title={e.title} small/><div className="card-body"><div className="card-meta"><span>{e.category}</span><span>{o?dt(o.startsAt,true):''}</span></div><h3>{e.title}</h3><p>{e.occurrences.length>1?`${e.occurrences.length} incontri · singolo o ciclo`:'Incontro singolo al club.'}</p><div className="card-bottom"><Badge tone={o?.remaining===0?'amber':'green'}>{o?.remaining===0?'Lista d’attesa':`${o?.remaining||0} posti disponibili`}</Badge><ArrowUpRight size={22}/></div></div></button>}
 function ArchiveCards(){return <div className="event-grid">{archive.map(e=><a className="event-card" href={e.source} target="_blank" rel="noreferrer" key={e.id}><Poster cover={e.cover} title={e.title} small/><div className="card-body"><div className="card-meta"><span>{e.category}</span><span>{e.date}</span></div><h3>{e.title}</h3><p>{e.description}</p><div className="card-bottom"><span className="text-link">Rivivi l’incontro</span><ArrowUpRight size={21}/></div></div></a>)}</div>}
 async function submitBooking(wait=false){if(!current)return;const ids=selectedOccurrence==='cycle'?current.occurrences.filter(o=>!o.cancelled).map(o=>o.id):[selectedOccurrence||current.occurrences[0].id];const payload={activityId:current.id,occurrenceIds:ids,participants};const result=await perform(()=>api(wait?'waitlist':'bookings',wait?payload:{...payload,method,idempotencyKey:bookKey||uuid()||uuid()}),wait?'Richiesta inserita in lista d’attesa.':'Prenotazione registrata.');if(result){if(result.checkoutUrl)location.assign(result.checkoutUrl);else go('account')}}
 function BookingPanel(){if(!current)return null;const ids=selectedOccurrence==='cycle'?current.occurrences.filter(o=>!o.cancelled).map(o=>o.id):[selectedOccurrence||current.occurrences[0].id];const remaining=Math.min(...current.occurrences.filter(o=>ids.includes(o.id)).map(o=>o.remaining));const total=participants.length*(ids.length>1&&current.cyclePriceCents!==null?current.cyclePriceCents:current.priceCents*ids.length);const full=participants.length>remaining;return <aside className="booking-panel"><span className="eyebrow">IL TUO PROSSIMO INCONTRO</span><h2>Ci vediamo qui.</h2><div className="price">{eur(current.priceCents)}<span> / persona, per incontro</span></div><Badge tone={remaining?'green':'amber'}>{remaining} posti disponibili</Badge><form onSubmit={e=>{e.preventDefault();if(!account){if(presentation){void chooseRole('user')}else go('login');return}if(!bookingStep){setBookingStep(1);return}submitBooking(full)}}>
 <label>Quando vuoi partecipare?<select value={selectedOccurrence||current.occurrences[0].id} onChange={e=>{setSelectedOccurrence(e.target.value);setBookingStep(0)}}>{current.occurrences.filter(o=>!o.cancelled).map(o=><option key={o.id} value={o.id}>{dt(o.startsAt,true)} · {o.remaining} posti</option>)}{current.occurrences.length>1&&<option value="cycle">Intero ciclo · {current.occurrences.length} incontri</option>}</select></label>
 <div className="quantity"><span>Partecipanti</span><div><button type="button" aria-label="Rimuovi partecipante" disabled={participants.length<=1} onClick={()=>{setParticipants(p=>p.slice(0,-1));setBookingStep(0)}}><Minus size={16}/></button><input aria-label="Numero partecipanti" type="number" min="1" value={participants.length} onChange={e=>{const n=Number(e.target.value);if(Number.isInteger(n)&&n>0&&n<=current.occurrences.reduce((n,o)=>Math.max(n,o.capacity),0)){setParticipants(p=>Array.from({length:n},(_,i)=>p[i]||{name:'',surname:'',cf:''}));setBookingStep(0)}}}/><button type="button" aria-label="Aggiungi partecipante" onClick={()=>{setParticipants(p=>[...p,{name:'',surname:'',cf:''}]);setBookingStep(0)}}><Plus size={16}/></button></div></div>
 {account&&<div className="participant-inputs">{participants.map((p,i)=><fieldset key={i}><legend>Partecipante {i+1}</legend><div className="two-col">{['name','surname'].map((k,j)=><label key={k}>{j?'Cognome':'Nome'}<input required maxLength={80} value={p[k as 'name']} onChange={e=>setParticipants(ps=>ps.map((x,n)=>n===i?{...x,[k]:e.target.value}:x))}/></label>)}</div><label>Codice fiscale<input required maxLength={16} value={p.cf} autoCapitalize="characters" onChange={e=>setParticipants(ps=>ps.map((x,n)=>n===i?{...x,cf:e.target.value.toUpperCase()}:x))}/></label></fieldset>)}</div>}
 {full&&<p className="notice warning">Sono disponibili soltanto {remaining} posti. Puoi entrare in lista per tutto il gruppo: nessuna prenotazione parziale.</p>}
 {!!bookingStep&&!full&&<><label>Modalità di pagamento<select value={method} onChange={e=>setMethod(e.target.value as 'onsite'|'online')}>{current.methods.includes('onsite')&&<option value="onsite">Sul posto</option>}{current.methods.includes('online')&&pub?.onlineReady&&<option value="online">Online con carta</option>}</select></label><div className="summary-line"><span>Contributo attività</span><strong>{eur(total)}</strong></div><p className="small muted">L’eventuale quota associativa è separata e si regolarizza sul posto. La tessera sarà verificata per ciascun partecipante.</p></>}
 {!!bookingStep&&<label className="check-label"><input type="checkbox" required checked={terms} onChange={e=>setTerms(e.target.checked)}/><span>Ho letto le condizioni: annullamento entro {dt(current.occurrences.filter(o=>ids.includes(o.id)).map(o=>o.cancellationDeadline).sort()[0],true)}. Rimborso contributo: {current.refundPercent===null?'da verificare con la segreteria':current.refundPercent+'%'}. Informerò gli accompagnatori del trattamento dei loro dati.</span></label>}
 <button className="button wide" disabled={busy}>{!account?'Accedi per prenotare':!bookingStep?'Continua':full?'Entra in lista d’attesa':'Conferma '+(method==='onsite'?'sul posto':'e paga')}<ArrowRight size={18}/></button><p className="small muted"><ShieldCheck size={15}/> Puoi prenotare anche senza tessera.</p></form></aside>}
 async function chooseRole(role:string){await api('demo/login',{role});await refresh();setTab('overview');go(role==='user'?'events':'admin')}
 const header=<>{presentation&&<div className="presenter"><strong>DEMO · CONTEROSSO</strong><span>Prova come</span>{[['user','Socio'],['manager','Responsabile'],['admin','Amministratore']].map(([id,label])=><button key={id} onClick={()=>chooseRole(id)}>{label}</button>)}<button onClick={async()=>{if(window.confirm('Ripristinare i dati iniziali della demo?')){await api('demo/reset');location.hash='/';location.reload()}}}>Ripristina demo</button></div>}<a className="skip-link" href="#main">Salta al contenuto</a>{pub?.mode==='demo'&&<div className="demo-bar">Ambiente dimostrativo · gli eventi di prova non sono appuntamenti reali · nessun pagamento o messaggio reale</div>}<header className="site-header"><a href="/" className="wordmark" onClick={e=>{e.preventDefault();go('home')}}>{brand}</a><nav aria-label="Navigazione principale" className={menu?'nav-open':''}>{[['events','Il calendario'],['about','Il club'],['membership','Diventa socio']].map(([v,t])=><a key={v} className={view===v?'active':''} href={paths[v]} onClick={e=>{e.preventDefault();go(v)}}>{t}</a>)}<a href="/contatti" onClick={e=>{e.preventDefault();go('contact')}}>Contatti</a></nav><div className="header-actions">{staff&&<button className="staff-link" onClick={()=>go('admin')} aria-label="Apri gestionale"><LayoutDashboard size={18}/></button>}<button className="button small-button" onClick={()=>go(account?'account':'login')}>{account?account.name:'Entra nel club'}<ArrowUpRight size={16}/></button><button className="icon-button menu-toggle" aria-label="Apri menu" aria-expanded={menu} onClick={()=>setMenu(!menu)}>{menu?<X/>:<Menu/>}</button></div></header></>;
 return <>{header}<main id="main">
 {view==='home'&&<><section className="hero container"><div className="hero-copy"><span className="eyebrow"><span className="live-dot"/> MOLFETTA / VIA ENRICO DE NICOLA, 12</span><h1>Qui si viene<br/>per <em>ascoltare.</em></h1><p>Al Conterosso può bastare la prima nota per far tacere una sala. Ci piacciono gli artisti che cercano un suono proprio e chi si prende il tempo di ascoltarli.</p><div className="hero-actions"><button className="button" onClick={()=>go('events')}>Scopri il programma<ArrowUpRight size={19}/></button><button className="text-link" onClick={()=>go('about')}>Conosci il club <ArrowRight size={17}/></button></div><div className="hero-location"><MapPin size={17}/>{content?.address||club.address}</div></div><div className="hero-art"><div className="vertical-caption">MUSICA · PAROLE · SGUARDI · PERSONE</div><div className="art-paper"><span className="paper-top">CONTEROSSO SOCIAL CLUB<br/>MOLFETTA, PUGLIA</span><div className="circle circle-one"/><div className="circle circle-two"/><div className="circle circle-three"/><div className="art-type">Difensori<br/>di <em>bellezza.</em></div><div className="paper-bottom"><span>DALLE PAROLE<br/>DELL’IDEATORE</span><ArrowUpRight size={46}/></div></div><span className="art-stamp">CONTEROSSO<br/><strong>MOLFETTA</strong><br/>SOCIAL CLUB</span></div></section><div className="ticker" aria-hidden="true"><span>MUSICA DAL VIVO</span><i>✳</i><span>STORIE DA CONDIVIDERE</span><i>✳</i><span>NUOVI SGUARDI</span><i>✳</i><span>CONTEROSSO SOCIAL CLUB</span></div><section className="section container"><div className="section-heading"><div><span className="eyebrow">IL CALENDARIO DEL CLUB</span><h2>I prossimi incontri<br/>al Conterosso.</h2></div><button className="text-link" onClick={()=>go('events')}>Tutte le attività <ArrowUpRight size={19}/></button></div>{future.length?<div className="event-grid">{future.slice(0,3).map(e=><EventCard key={e.id} e={e}/>)}</div>:<Empty title="Il prossimo incontro prende forma.">Il nuovo calendario sarà pubblicato qui. Nel frattempo, seguici su Facebook.</Empty>}</section><section className="club-band"><div className="container band-grid"><span className="eyebrow">DAL DIARIO DEL CLUB</span><div><h2>Una sera con<br/><em>i tre Mostri.</em></h2><p>Dopo il concerto di Vince Abbracciante, Antonio Di Lorenzo e Dado Penta, l’ideatore ha ringraziato i musicisti e chi era in sala. Li ha chiamati «prodigiosi difensori di bellezza».</p><button className="button light" onClick={()=>go('about')}>Leggi la storia del club<ArrowUpRight size={18}/></button></div><div className="band-symbol" aria-hidden="true">✳</div></div></section><section className="section container"><div className="section-heading"><div><span className="eyebrow">TRACCE DI QUELLO CHE SIAMO</span><h2>È successo al club.</h2></div><button className="text-link" onClick={()=>go('archive')}>L’archivio <ArrowUpRight size={19}/></button></div><ArchiveCards/></section><section className="membership-banner container"><div><span className="eyebrow">UN PICCOLO GESTO. UNA GRANDE APPARTENENZA.</span><h2>Dietro ogni incontro<br/><em>ci sono i soci.</em></h2><p>Prenota anche se non sei ancora socio. Completa il tesseramento prima dell’attività, anche sul posto.</p></div><button className="button" onClick={()=>go('membership')}>Scopri il tesseramento<ArrowUpRight size={20}/></button></section></>}
 {view==='events'&&<section className="section container"><div className="page-intro"><span className="eyebrow">SCEGLI IL TUO PROSSIMO INCONTRO</span><h1>Il calendario.</h1><p>Musica, parole e occasioni per ritrovarsi. C’è spazio per la tua curiosità.</p></div><div className="filters"><label className="search-field"><Search size={19}/><input aria-label="Cerca attività" placeholder="Cerca un’attività…" value={query} onChange={e=>setQuery(e.target.value)}/></label><input aria-label="Filtra per data" type="date" value={dateFilter} onChange={e=>setDateFilter(e.target.value)}/><div className="filter-chips">{['Tutte',...new Set(future.map(e=>e.category))].map(c=><button key={c} onClick={()=>setCategory(c)} className={category===c?'selected':''}>{c}</button>)}</div></div>{filtered.length?<div className="event-grid">{filtered.map(e=><EventCard key={e.id} e={e}/>)}</div>:<Empty title={future.length?'Nessuna attività corrisponde ai filtri.':'Stiamo preparando nuovi incontri.'}>{future.length?<button className="text-link" onClick={()=>{setQuery('');setCategory('Tutte');setDateFilter('')}}>Azzera i filtri</button>:<a href={club.facebook} target="_blank" rel="noreferrer">Seguici su Facebook per le novità.</a>}</Empty>}</section>}
 {view==='event'&&<section className="section container">{current?<><button className="text-link back-link" onClick={()=>go('events')}>← Torna al calendario</button><div className="event-layout"><div><Poster cover={current.cover} title={current.title}/><div className="event-description"><span className="eyebrow">{current.category}{current.sample?' / ATTIVITÀ DIMOSTRATIVA':''}</span><h1>{current.title}</h1><p>{current.description}</p><div className="info-row"><MapPin/>{current.location}</div><h3>Gli appuntamenti</h3>{current.occurrences.map(o=><div className="occurrence" key={o.id}><CalendarDays size={20}/><div><strong>{dt(o.startsAt)}</strong><p className="small muted">{o.cancelled?'Annullato':`${o.remaining} posti disponibili · capienza ${o.capacity}`}</p></div></div>)}<div className="notice"><Ticket/><div><strong>La prenotazione è aperta a tutti.</strong><p>Per entrare, ciascun partecipante dovrà avere una tessera valida. Puoi completarla anche sul posto.</p></div></div></div></div>{current.status==='published'?BookingPanel():<Empty title="Questa attività non è prenotabile.">Consulta il calendario per i prossimi incontri.</Empty>}</div></>:<Empty title="Attività non trovata.">Torna al calendario per scegliere un incontro.</Empty>}</section>}
 {view==='about'&&<section className="section container"><div className="page-intro"><span className="eyebrow">CONTEROSSO SOCIAL CLUB / MOLFETTA</span><h1>Il nostro modo<br/>di <em>fare cultura.</em></h1></div><div className="about-layout"><div className="about-art" aria-hidden="true"><span>ASCOLTARE.<br/>SCOPRIRE.<br/>CONDIVIDERE.</span><b>✳</b></div><div><h2>Una sala che ascolta.</h2><p className="lead">{aboutText}</p><p>Dopo la serata con Vince Abbracciante, Antonio Di Lorenzo e Dado Penta, l’ideatore ha scritto: «Grazie ai tre Mostri che ci hanno regalato tutto ciò.» A colpirlo erano stati lo studio dietro ogni nota e il divertimento con cui i tre musicisti lo avevano condiviso con la sala.</p><div className="values">{[[Music2,'La musica','Ricerca e spazio a chi muove i primi passi sul palco.'],[BookOpen,'Le parole','Libri, politica e confronto tra persone che la pensano diversamente.'],[Camera,'Gli sguardi','Mostre e laboratori dove si impara provando.']].map(([Icon,title,text]:any)=><div key={title}><Icon size={23}/><strong>{title}</strong><span>{text}</span></div>)}</div><p className="club-principles">Lo statuto ci definisce un’associazione autonoma, pluralista, democratica e antifascista. Per noi questo significa anche tenere accessibili le attività e aprire la sala a iniziative di solidarietà.</p><a className="button" href={club.facebook} target="_blank" rel="noreferrer">La nostra pagina Facebook<ArrowUpRight size={18}/></a></div></div></section>}
 {view==='membership'&&<section className="section container"><div className="page-intro"><span className="eyebrow">DIVENTA SOCIO</span><h1>Un posto in cui<br/><em>esserci davvero.</em></h1><p>{content?.membershipText}</p></div><div className="membership-grid"><div className="membership-card"><span>CONTEROSSO<br/>SOCIAL CLUB</span><span className="card-sun">✳</span><div><small>LA TUA TESSERA</small><strong>Parte di qualcosa.</strong><small>MOLFETTA / CULTURA CONDIVISA</small></div></div><div><h2>Tre passi, con semplicità.</h2>{[['01','Registrati sul sito','Crea il tuo account con email, codice fiscale e codice di verifica.'],['02','Scegli un’attività','Puoi prenotare per te e per un gruppo anche senza tessera.'],['03','Completa il tesseramento','La tessera deve essere valida prima dell’ingresso. La segreteria ti accompagna nella procedura.']].map(([n,t,p])=><div className="number-step" key={n}><span>{n}</span><div><h3>{t}</h3><p>{p}</p></div></div>)}<div className="notice"><strong>Quota associativa: {content?.membershipFeeCents!=null?eur(content.membershipFeeCents):'da confermare con la segreteria'}</strong><p>La quota è distinta dai contributi delle attività. Registrarsi o pagare non equivale automaticamente all’ammissione come socio.</p></div><button className="button" onClick={()=>go(account?'account':'login')}>{account?'La tua area personale':'Crea il tuo account'}<ArrowRight size={18}/></button></div></div></section>}
 {view==='archive'&&<section className="section container"><div className="page-intro"><span className="eyebrow">IL NOSTRO ARCHIVIO</span><h1>Gli incontri restano.</h1><p>Una selezione di attività passate. Ogni scheda rimanda alla fonte pubblica del racconto.</p></div><ArchiveCards/></section>}
 {view==='gallery'&&<section className="section container"><div className="page-intro"><span className="eyebrow">SGUARDI SUL CLUB</span><h1>La galleria.</h1></div>{content?.gallery?.length?<div className="gallery-grid">{content.gallery.map((img,i)=><figure key={i}><img src={img.url} alt={img.alt} loading="lazy"/><figcaption>{img.alt}</figcaption></figure>)}</div>:<Empty title="Le immagini del club sono su Facebook.">Le fotografie autorizzate saranno raccolte anche qui. <a href={club.facebook} target="_blank" rel="noreferrer">Visita la pagina del club ↗</a></Empty>}</section>}
 {view==='contact'&&<section className="section container"><div className="page-intro"><span className="eyebrow">CONTATTI</span><h1>Passa a trovarci.<br/><em>Oppure scrivici.</em></h1></div><div className="contact-grid"><div className="contact-panel"><MapPin size={28}/><h3>Ci trovi a Molfetta</h3><p>{content?.address||club.address}</p><a className="text-link" target="_blank" rel="noreferrer" href={'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(content?.address||club.address)}>Indicazioni stradali <ArrowUpRight size={18}/></a></div><div className="contact-panel"><Mail size={28}/><h3>Restiamo in contatto</h3><a href={'mailto:'+(content?.contactEmail||club.email)}>{content?.contactEmail||club.email}</a><a href={'tel:'+(content?.phone||club.phone).replace(/\s/g,'')}>{content?.phone||club.phone}</a><a className="text-link" target="_blank" rel="noreferrer" href={club.facebook}>Facebook <ArrowUpRight size={18}/></a></div></div></section>}
 {view==='login'&&<section className="section container login-layout"><div className="login-copy"><span className="eyebrow">BENTORNATO AL CLUB</span><h1>Il prossimo incontro<br/>inizia <em>qui.</em></h1><p>Una sola area per le tue prenotazioni, la tessera e le persone che vengono con te.</p><div className="login-art" aria-hidden="true">✳</div></div><div className="login-panel"><h2>{challenge?'Controlla la tua email.':login.register?'Benvenuto nel club.':'Accedi alla tua area.'}</h2>{!challenge?<form onSubmit={async e=>{e.preventDefault();const r=await perform(()=>api('auth/request',login),'');if(r){setChallenge(r.challengeId);setDemoCode(r.demoCode||'');setToast(r.message)}}}>{login.register&&<><div className="two-col"><label>Nome<input required autoComplete="given-name" value={login.name} onChange={e=>setLogin({...login,name:e.target.value})}/></label><label>Cognome<input required autoComplete="family-name" value={login.surname} onChange={e=>setLogin({...login,surname:e.target.value})}/></label></div><label>Cellulare<input type="tel" required autoComplete="tel" value={login.phone} onChange={e=>setLogin({...login,phone:e.target.value})}/></label></>}<label>Email<input type="email" required autoComplete="email" value={login.email} onChange={e=>setLogin({...login,email:e.target.value})}/></label><label>Codice fiscale<input required maxLength={16} value={login.cf} autoCapitalize="characters" onChange={e=>setLogin({...login,cf:e.target.value.toUpperCase()})}/></label>{login.register&&<><label className="check-label"><input required type="checkbox"/><span>Ho letto l’informativa sul trattamento dei dati. L’account è distinto dall’iscrizione all’associazione.</span></label><label className="check-label"><input type="checkbox" checked={login.whatsapp} onChange={e=>setLogin({...login,whatsapp:e.target.checked})}/><span>Desidero ricevere su WhatsApp le comunicazioni relative alle attività.</span></label></>}<p className="small muted">Riceverai un codice numerico monouso via email. Il codice fiscale serve a identificarti, non è una password.</p><button className="button wide" disabled={busy}>Invia il codice<ArrowRight size={18}/></button><button type="button" className="text-link center" onClick={()=>setLogin({...login,register:!login.register})}>{login.register?'Hai già un account? Accedi':'Prima volta qui? Registrati'}</button></form>:<form onSubmit={async e=>{e.preventDefault();const r=await perform(()=>api('auth/verify',{challengeId:challenge,code:otp,totp}),'Accesso effettuato.');if(r){setChallenge('');setOtp('');go(r.account.role==='user'?'account':'admin')}}}><p>Inserisci il codice ricevuto all’indirizzo indicato. È valido per 10 minuti.</p><label>Codice di verifica<input className="otp-input" autoComplete="one-time-code" inputMode="numeric" pattern="[0-9]{8}" maxLength={8} required value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,''))}/></label><label>Codice autenticatore (solo operatori)<input inputMode="numeric" maxLength={6} value={totp} onChange={e=>setTotp(e.target.value)}/></label>{demoCode&&<p className="notice">Demo locale: usa <strong>{demoCode}</strong>. Non viene inviata alcuna email.</p>}<button className="button wide" disabled={busy}>Verifica e accedi<Check size={18}/></button><button className="text-link center" type="button" onClick={()=>{setChallenge('');setOtp('')}}>Torna ai dati di accesso</button></form>}{pub?.mode==='demo'&&!challenge&&<div className="demo-accounts"><span className="eyebrow">PROVA I TRE RUOLI</span>{pub.demoAccounts.map(a=><button key={a.role} onClick={()=>presentation?chooseRole(a.role):setLogin({...login,email:a.email,cf:a.cf,register:false})}>{a.role==='user'?'Utente':a.role==='manager'?'Responsabile':'Amministratore'}<ArrowUpRight size={16}/></button>)}</div>}</div></section>}
 {view==='account'&&<section className="section container">{!account?<Empty title="La tua area ti aspetta."><button className="button" onClick={()=>go('login')}>Accedi</button></Empty>:<><div className="section-heading"><div><span className="eyebrow">LA TUA AREA PERSONALE</span><h1>Ciao, {account.name}<span className="brand-dot">.</span></h1></div><button className="text-link" onClick={()=>perform(async()=>{await api('auth/logout',{});go('home')},'Sei uscito dal tuo account.')}><LogOut size={17}/> Esci</button></div><div className="account-grid"><div><h2>Le tue prenotazioni</h2>{me.bookings.filter((b:Booking)=>b.ownerId===account.id).length?me.bookings.filter((b:Booking)=>b.ownerId===account.id).map((b:Booking)=><div className="booking-card" key={b.id}><div className="row"><Badge tone={b.state==='confirmed'?'green':'amber'}>{statusText[b.state]}</Badge><span className="small muted">{b.id.slice(0,8)}</span></div><h3>{pub?.activities.find(e=>e.id===b.activityId)?.title||'Attività'}</h3><div className="booking-facts"><span><Users size={16}/>{b.participants.length} partecipanti</span><span><Ticket size={16}/>{b.method==='onsite'?'Sul posto':'Online'}</span></div><div className="summary-line"><span>Contributo attività</span><strong>{eur(b.totalCents)}</strong></div><div className="summary-line"><span>Ancora da versare</span><strong>{eur(Math.max(0,b.totalCents-b.paidCents))}</strong></div>{b.refundDueCents>0&&<p className="notice warning">Rimborso da gestire: {eur(b.refundDueCents)}</p>}<details><summary>I partecipanti</summary>{b.participants.map(p=><div className="summary-line" key={p.personId}><span>{p.name} {p.surname}</span><Badge tone={me.people.find((x:any)=>x.id===p.personId)?.active?'green':'amber'}>{me.people.find((x:any)=>x.id===p.personId)?.active?'Tessera valida':'Da regolarizzare'}</Badge></div>)}</details>{['held','confirmed'].includes(b.state)&&<button className="text-link danger" onClick={()=>setCancelId(b.id)}>Annulla prenotazione</button>}</div>):<Empty title="Il prossimo incontro è tutto da scegliere."><button className="button" onClick={()=>go('events')}>Esplora il calendario<ArrowRight size={17}/></button></Empty>}<h2 className="top-space">La tua lista d’attesa</h2>{me.waitlist.filter((w:any)=>w.ownerId===account.id).map((w:any)=><div className="booking-card" key={w.id}><Badge>{statusText[w.state]}</Badge><h3>{pub?.activities.find(e=>e.id===w.activityId)?.title}</h3><p>{w.quantity} posti richiesti</p>{w.state==='offered'&&<><p>Conferma entro {new Date(w.expiresAt).toLocaleString('it-IT')}</p><button disabled={busy} className="button" onClick={()=>perform(()=>api('wait-accept',{id:w.id,method:'onsite'}),'Offerta accettata.')}>Accetta e paga sul posto</button></>}{['waiting','offered'].includes(w.state)&&<button className="text-link" onClick={()=>perform(()=>api('wait-withdraw',{id:w.id}),'Richiesta ritirata.')}>Ritira richiesta</button>}</div>)}</div><aside><div className="personal-card"><span className="eyebrow">LA TUA TESSERA</span><Ticket size={36}/><h3>{account.name} {account.surname}</h3><Badge tone={me.people.find((p:any)=>p.id===account.cfKey)?.active?'green':'amber'}>{me.people.find((p:any)=>p.id===account.cfKey)?.active?'Tessera valida':'Tesseramento da completare'}</Badge><p>Puoi prenotare anche senza tessera. Regolarizza la tua posizione prima dell’ingresso.</p><button className="text-link" onClick={()=>go('membership')}>Come funziona<ArrowRight size={16}/></button></div><div className="panel top-space"><h3>Le tue preferenze</h3><label className="check-label"><input type="checkbox" checked={account.whatsapp} onChange={e=>perform(()=>api('profile',{whatsapp:e.target.checked}),'Preferenza aggiornata.')}/><span>Comunicazioni operative su WhatsApp</span></label><p className="small muted">Le email relative alle prenotazioni rimangono attive.</p></div></aside></div></>}</section>}
 {view==='admin'&&<div className="admin-layout">{!staff?<div className="container section"><Empty title="Area riservata agli operatori."><button className="button" onClick={()=>go('login')}>Accedi con il tuo account</button></Empty></div>:<><aside className="admin-sidebar"><span className="eyebrow">GESTIONALE DEL CLUB</span><h3>{account!.role==='admin'?'Amministrazione':'Le mie attività'}</h3>{[['overview',LayoutDashboard,'Panoramica'],['events',CalendarDays,'Attività'],['bookings',Users,'Prenotazioni e presenze'],...(account!.role==='admin'?[['members',Ticket,'Soci e tessere']]:[]),['finance',ShieldCheck,'Incassi'],['notifications',Mail,'Comunicazioni'],...(account!.role==='admin'?[['settings',Settings,'Sito e regole']]:[])].map(([id,Icon,title]:any)=><button key={id} className={tab===id?'selected':''} onClick={()=>setTab(id)}><Icon size={18}/>{title}</button>)}<div className="sidebar-bottom"><small>Accesso come</small><strong>{account!.name} {account!.surname}</strong><button onClick={()=>go('account')}>La mia area personale<ArrowUpRight size={16}/></button></div></aside><section className="admin-main"><div className="section-heading"><div><span className="eyebrow">CONTEROSSO / {account!.role==='admin'?'AMMINISTRAZIONE':'RESPONSABILE'}</span><h1>{({overview:'Il club, a colpo d’occhio.',events:'Le attività.',bookings:'Persone, prima di tutto.',members:'Soci e tesseramento.',finance:'Ogni contributo conta.',notifications:'Restiamo in contatto.',settings:'Il tuo club, le tue regole.'} as any)[tab]}</h1></div><button className="icon-button" aria-label="Aggiorna dati" onClick={()=>perform(refresh,'Dati aggiornati.')}><RefreshCw size={20}/></button></div>
 {tab==='overview'&&<><div className="kpi-grid">{[['Prenotazioni confermate',me.bookings.filter((b:Booking)=>b.state==='confirmed').length],['Partecipanti',me.bookings.filter((b:Booking)=>b.state==='confirmed').reduce((n:number,b:Booking)=>n+b.participants.length,0)],['Da incassare sul posto',eur(me.bookings.filter((b:Booking)=>b.state==='confirmed'&&b.method==='onsite').reduce((n:number,b:Booking)=>n+b.totalCents-b.paidCents,0))],['Tessere da regolarizzare',me.people.filter((p:any)=>!p.active).length]].map(([t,n])=><div className="kpi" key={t}><span>{t}</span><strong>{n}</strong></div>)}</div>{me.settings?.waitPolicy==='unset'&&<div className="notice warning"><AlertCircle/><div><strong>Lista d’attesa: scegli la regola di assegnazione.</strong><p>Le richieste vengono raccolte. Le offerte automatiche si attiveranno dopo la scelta tra ordine rigoroso e primo gruppo compatibile.</p></div></div>}<div className="section-heading top-space"><h2>Le prossime attività</h2><button className="text-link" onClick={()=>setTab('events')}>Gestisci tutte<ArrowRight size={17}/></button></div><div className="table-wrap"><table><thead><tr><th>Attività</th><th>Stato</th><th>Incontri</th><th>Capienza</th><th/></tr></thead><tbody>{me.activities.map((e:Activity)=><tr key={e.id}><td><strong>{e.title}</strong><small>{e.category}</small></td><td><Badge>{statusText[e.status]}</Badge></td><td>{e.occurrences.length}</td><td>{e.occurrences[0].capacity}</td><td><button className="text-link" onClick={()=>setEditor(e)}>Gestisci<ChevronRight size={16}/></button></td></tr>)}</tbody></table></div><div className="two-col top-space"><div className="panel"><Mail/><h3>Comunicazioni</h3><p>{me.jobs.filter((j:any)=>['failed','unknown'].includes(j.state)).length} invii da verificare · {me.jobs.filter((j:any)=>j.state==='pending').length} in coda</p><button className="text-link" onClick={()=>setTab('notifications')}>Apri storico<ArrowRight size={17}/></button></div><div className="panel"><Download/><h3>I dati, quando servono</h3><p>Esporta prenotazioni, partecipanti e incassi delle attività a cui hai accesso.</p><a href="/api/export" className="text-link">Scarica Excel<Download size={17}/></a></div></div></>}
 {tab==='events'&&<><div className="row toolbar"><p className="muted">{me.activities.length} attività nel tuo ambito</p>{account!.role==='admin'&&<button className="button" onClick={()=>setEditor(null)}><Plus size={18}/>Nuova attività</button>}</div><div className="admin-event-grid">{me.activities.map((e:Activity)=><div className="panel" key={e.id}><Badge>{statusText[e.status]}</Badge><h3>{e.title}</h3><p>{e.description}</p>{e.occurrences.map(o=><div className="summary-line" key={o.id}><span>{dt(o.startsAt,true)}</span><strong>{o.capacity} posti</strong></div>)}<div className="row top-space"><button className="button secondary" onClick={()=>setEditor(e)}>Modifica</button><a className="text-link" href={'/api/export?activity='+e.id}>Excel<Download size={17}/></a></div></div>)}</div></>}
 {tab==='bookings'&&<><div className="row toolbar"><p className="muted">Presenze individuali, per ogni incontro.</p><a className="button secondary" href="/api/export"><Download size={18}/>Esporta Excel</a></div>{me.bookings.filter((b:Booking)=>me.activities.some((e:Activity)=>e.id===b.activityId)).length===0?<Empty title="Le prenotazioni appariranno qui.">Pubblica un’attività e condividi il calendario.</Empty>:me.bookings.filter((b:Booking)=>me.activities.some((e:Activity)=>e.id===b.activityId)).map((b:Booking)=><div className="panel booking-admin" key={b.id}><div className="row"><div><Badge tone={b.state==='confirmed'?'green':'amber'}>{statusText[b.state]}</Badge><h3>{me.activities.find((e:Activity)=>e.id===b.activityId)?.title}</h3></div><span>{eur(b.totalCents-b.paidCents)} da incassare</span></div>{b.occurrenceIds.map(oid=><div key={oid}><p className="small muted">{dt(me.activities.find((e:Activity)=>e.id===b.activityId)?.occurrences.find((o:any)=>o.id===oid)?.startsAt||new Date().toISOString())}</p>{b.participants.map(p=>{const person=me.people.find((x:any)=>x.id===p.personId);const status=b.attendance?.[`${oid}_${p.personId}`];return <div className="checkin-row" key={p.personId}><div><strong>{p.name} {p.surname}</strong><Badge tone={person?.active?'green':'amber'}>{person?.active?'Tessera valida':'Da regolarizzare'}</Badge></div><div className="row">{status&&<span className="small">{status==='present'?'Presente':'Assente'}</span>}<button className="button tiny" disabled={busy||b.state!=='confirmed'||!person?.active} onClick={()=>perform(()=>api('checkin',{bookingId:b.id,personId:p.personId,occurrenceId:oid,status:'present'}),'Presenza registrata.')}><Check size={15}/>Presente</button><button className="text-link" disabled={busy||b.state!=='confirmed'} onClick={()=>perform(()=>api('checkin',{bookingId:b.id,personId:p.personId,occurrenceId:oid,status:'absent'}),'Assenza registrata.')}>Assente</button>{!person?.active&&(account!.role==='admin'||me.settings?.onsiteDelegates?.includes(account!.id))&&<button className="text-link" onClick={()=>setMemberEditor(person)}>Tessera</button>}</div></div>})}</div>)}{b.state==='confirmed'&&b.method==='onsite'&&b.totalCents>b.paidCents&&<CashForm remaining={b.totalCents-b.paidCents} busy={busy} onSave={amount=>perform(()=>api('cash',{id:b.id,amountCents:amount,idempotencyKey:uuid()}),'Incasso registrato.')}/>}</div>)}</>}
 {tab==='members'&&account!.role==='admin'&&<><div className="panel"><h3>Importa l’archivio soci</h3><p>Carica un file .xlsx. Prima dell’importazione potrai verificare righe e conflitti. Le tessere importate rimangono in verifica.</p><p className="small muted">Colonne: nome, cognome, codice_fiscale, numero_tessera, dal, al, quota_euro. Date AAAA-MM-GG.</p><input aria-label="File Excel soci" type="file" accept=".xlsx" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;const data=new FormData();data.append('file',file);const r=await perform(async()=>{if(presentation)return (await import('../../demo/browser-api')).demoImport(file);const response=await fetch('/api/import/preview',{method:'POST',body:data});const json=await response.json();if(!response.ok)throw new Error(json.error);return json},'Anteprima pronta.');if(r)setImportPreview(r)}}/>{importPreview&&<><p>{importPreview.rows.filter((r:any)=>!r.errors.length).length} righe importabili su {importPreview.rows.length}</p><div className="table-wrap"><table><thead><tr><th>Nome</th><th>Cognome</th><th>Esito</th></tr></thead><tbody>{importPreview.rows.slice(0,50).map((r:any,i:number)=><tr key={i}><td>{r.name}</td><td>{r.surname}</td><td>{r.errors.join('; ')||'Importabile'}</td></tr>)}</tbody></table></div><button className="button" disabled={busy} onClick={async()=>{const r=await perform(()=>api('import/commit',importPreview),'Importazione completata.');if(r)setImportPreview(null)}}>Conferma righe valide</button></>}</div><div className="table-wrap top-space"><table><thead><tr><th>Socio / partecipante</th><th>Tessera</th><th>Storico</th><th/></tr></thead><tbody>{me.people.map((p:any)=><tr key={p.id}><td><strong>{p.name} {p.surname}</strong></td><td><Badge tone={p.active?'green':'amber'}>{p.active?'Attiva':'Da verificare'}</Badge></td><td>{p.membership?.map((m:any)=>`${m.card} · ${m.from} / ${m.to}`).join('; ')||'Nessuna tessera'}</td><td><button className="text-link" onClick={()=>setMemberEditor(p)}>Registra tessera<Plus size={16}/></button></td></tr>)}</tbody></table></div><h2 className="top-space">Utenti e ruoli</h2><div className="table-wrap"><table><thead><tr><th>Utente</th><th>Email</th><th>Ruolo</th></tr></thead><tbody>{me.accounts.map((a:Account)=><tr key={a.id}><td>{a.name} {a.surname}</td><td>{a.email}</td><td><select aria-label={'Ruolo di '+a.name} value={a.role} disabled={a.id===account!.id||busy} onChange={e=>perform(()=>api('roles',{id:a.id,role:e.target.value}),'Ruolo aggiornato.')}><option value="user">Utente</option><option value="manager">Responsabile</option><option value="admin">Amministratore</option></select></td></tr>)}</tbody></table></div></>}
 {tab==='finance'&&<><div className="kpi-grid">{[['Contributi attività',eur(me.ledger.filter((l:any)=>l.type==='activity').reduce((n:number,l:any)=>n+l.amountCents,0))],['Quote associative',eur(me.ledger.filter((l:any)=>l.type==='membership').reduce((n:number,l:any)=>n+l.amountCents,0))],['Rimborsi effettuati',eur(me.ledger.filter((l:any)=>l.type==='refund').reduce((n:number,l:any)=>n+l.amountCents,0))]].map(([t,n])=><div className="kpi" key={t}><span>{t}</span><strong>{n}</strong></div>)}</div><div className="table-wrap top-space"><table><thead><tr><th>Data</th><th>Tipo</th><th>Modalità</th><th>Importo</th></tr></thead><tbody>{me.ledger.map((l:any)=><tr key={l.id}><td>{new Date(l.createdAt).toLocaleDateString('it-IT')}</td><td>{{activity:'Contributo attività',membership:'Quota associativa',refund:'Rimborso'}[l.type as 'activity']}</td><td>{l.method==='onsite'?'Sul posto':'Online'}</td><td>{eur(l.amountCents)}</td></tr>)}</tbody></table></div>{account!.role==='admin'&&me.bookings.filter((b:Booking)=>b.refundDueCents>0).map((b:Booking)=><div className="notice warning" key={b.id}><span>Rimborso da gestire · {b.id.slice(0,8)} · {eur(b.refundDueCents)}</span><button className="button secondary" disabled={busy||!b.paymentIntent} onClick={()=>perform(()=>api('refund',{id:b.id}),'Richiesta di rimborso elaborata.')}>Rimborsa online</button></div>)}<p className="notice">Il registro distingue quote e contributi. La tipologia dei documenti da emettere va validata con il consulente dell’associazione prima dell’attivazione reale.</p></>}
 {tab==='notifications'&&<><div className="panel"><h3>Una comunicazione ai partecipanti</h3><form onSubmit={e=>{e.preventDefault();perform(()=>api('notify',notification),'Comunicazione inserita in coda.')}}><label>Attività<select required value={notification.activityId} onChange={e=>setNotification({...notification,activityId:e.target.value})}><option value="">Scegli un’attività</option>{me.activities.map((e:Activity)=><option key={e.id} value={e.id}>{e.title}</option>)}</select></label><label>Messaggio<textarea required rows={3} maxLength={2000} value={notification.message} onChange={e=>setNotification({...notification,message:e.target.value})}/></label><button className="button" disabled={busy}><Send size={17}/>Prepara comunicazione</button></form></div><div className="section-heading top-space"><h2>Storico degli invii</h2>{account!.role==='admin'&&<button className="button secondary" disabled={busy} onClick={()=>perform(()=>api('run-jobs',{}),pub?.mode==='demo'?'Coda simulata: nessun messaggio inviato.':'Coda elaborata: controlla gli esiti.')}><RefreshCw size={17}/>Elabora coda</button>}</div><div className="table-wrap"><table><thead><tr><th>Tipo</th><th>Canale</th><th>Programmazione</th><th>Esito</th></tr></thead><tbody>{me.jobs.map((j:any)=><tr key={j.id}><td>{{confirmation:'Conferma prenotazione','staff-new':'Nuova prenotazione · admin','staff-reminder':'Avviso T−5h',reminder:'Promemoria T−2h',change:'Comunicazione','wait-offer':'Offerta lista d’attesa'}[j.type as 'confirmation']}</td><td>{j.channel}</td><td>{new Date(j.dueAt).toLocaleString('it-IT')}</td><td><Badge tone={j.state==='failed'||j.state==='unknown'?'amber':''}>{j.providerId?.startsWith('DEMO_')?'Simulato':statusText[j.state]}</Badge>{j.detail&&<small>{j.detail}</small>}</td></tr>)}</tbody></table></div><p className="small muted">Accettato dal provider non significa consegnato. La consegna viene aggiornata dagli esiti del servizio.</p></>}
 {tab==='settings'&&account!.role==='admin'&&<SettingsForm settings={me.settings} accounts={me.accounts} busy={busy} onSave={s=>perform(()=>api('settings',s),'Contenuti e regole aggiornati.')}/>}
 </section></>}</div>}
 </main><footer className="footer"><div className="container footer-top"><div><a className="wordmark" href="/" onClick={e=>{e.preventDefault();go('home')}}>{brand}</a><p>Musica, arte e impegno civile<br/>in via Enrico De Nicola, a Molfetta.</p></div><div><span className="eyebrow">ESPLORA</span>{[['events','Calendario'],['about','Chi siamo'],['archive','Archivio'],['gallery','Galleria']].map(([v,t])=><a key={v} href={paths[v]} onClick={e=>{e.preventDefault();go(v)}}>{t}</a>)}</div><div><span className="eyebrow">PARTECIPA</span><button onClick={()=>go('membership')}>Tesseramento</button><button onClick={()=>go('account')}>Area personale</button><a href={club.facebook} target="_blank" rel="noreferrer">Facebook ↗</a></div><div><span className="eyebrow">VIENI A TROVARCI</span><p>{content?.address||club.address}</p><a href={'mailto:'+(content?.contactEmail||club.email)}>{content?.contactEmail||club.email}</a><a href={'tel:'+(content?.phone||club.phone).replace(/\s/g,'')}>{content?.phone||club.phone}</a></div></div><div className="container footer-bottom"><span>© {new Date().getFullYear()} Conterosso Social Club</span><span>{pub?.mode==='demo'?'Anteprima di sviluppo · dati di prova':'Informative e condizioni definitive in preparazione'}</span></div></footer>
 {toast&&<div className="toast" role="status" aria-live="polite"><AlertCircle size={20}/><span>{toast}</span><button aria-label="Chiudi messaggio" onClick={()=>setToast('')}><X size={17}/></button></div>}
 {editor!==false&&<Dialog title={editor?'Modifica attività':'Nuova attività'} onClose={()=>setEditor(false)}><EventForm activity={editor} admin={account?.role==='admin'} accounts={me?.accounts||[]} busy={busy} onSave={async d=>{const r=await perform(()=>api(editor?'event-update':'events',editor?{id:editor.id,version:editor.version,patch:d}:d),'Attività salvata.');if(r)setEditor(false)}}/></Dialog>}
 {memberEditor&&<Dialog title={'Tesseramento · '+memberEditor.name+' '+memberEditor.surname} onClose={()=>setMemberEditor(null)}><MembershipForm settings={me?.settings} busy={busy} onSave={async d=>{const r=await perform(()=>api('membership',{...d,personId:memberEditor.id,idempotencyKey:uuid()}),'Tessera registrata.');if(r)setMemberEditor(null)}}/></Dialog>}
 {cancelId&&<Dialog title="Annullare la prenotazione?" onClose={()=>setCancelId('')}><p>I posti saranno liberati per gli altri partecipanti. L’eventuale rimborso seguirà le condizioni acquisite al momento della prenotazione.</p><div className="row"><button className="button secondary" onClick={()=>setCancelId('')}>Mantieni prenotazione</button><button className="button" disabled={busy} onClick={async()=>{const r=await perform(()=>api('cancel',{id:cancelId}),'Prenotazione annullata.');if(r)setCancelId('')}}>Conferma annullamento</button></div></Dialog>}
 </>;
}
function CashForm({remaining,busy,onSave}:{remaining:number;busy:boolean;onSave:(n:number)=>void}){const [amount,setAmount]=useState(remaining/100);return <form className="cash-form" onSubmit={e=>{e.preventDefault();onSave(Math.round(amount*100))}}><label>Incasso sul posto (€)<input type="number" min="0.01" max={remaining/100} step="0.01" value={amount} required onChange={e=>setAmount(Number(e.target.value))}/></label><button className="button secondary" disabled={busy}>Registra incasso</button></form>}
function EventForm({activity,admin,accounts,busy,onSave}:{activity:Activity|null;admin:boolean;accounts:Account[];busy:boolean;onSave:(v:any)=>void}){const tomorrow=new Date(Date.now()+86400000).toISOString().slice(0,16);const [d,setD]=useState({title:activity?.title||'',description:activity?.description||'',category:activity?.category||'Musica',location:activity?.location||club.address,status:activity?.status||'draft',price:(activity?.priceCents||0)/100,cycle:activity?.cyclePriceCents!=null?activity.cyclePriceCents/100:0,cover:activity?.cover||'music',refund:activity?.refundPercent??100,manager:activity?.managers[0]||'',online:activity?.methods.includes('online')||false,onsite:activity?.methods.includes('onsite')??true});const [occurrences,setOccurrences]=useState(activity?.occurrences||[{id:uuid(),startsAt:new Date(tomorrow).toISOString(),endsAt:new Date(Date.parse(tomorrow)+7200000).toISOString(),capacity:80,bookingDeadline:new Date(Date.parse(tomorrow)-1800000).toISOString(),cancellationDeadline:new Date(Date.parse(tomorrow)-86400000).toISOString()}]);return <form onSubmit={e=>{e.preventDefault();const patch=admin?{title:d.title,description:d.description,category:d.category,location:d.location,status:d.status,priceCents:Math.round(d.price*100),cyclePriceCents:occurrences.length>1?Math.round(d.cycle*100):null,methods:[...(d.onsite?['onsite']:[]),...(d.online?['online']:[])],managers:d.manager?[d.manager]:[],occurrences,cover:d.cover,refundPercent:d.refund}:{description:d.description,location:d.location,occurrences};onSave(patch)}}><label>Titolo<input value={d.title} disabled={!admin} required onChange={e=>setD({...d,title:e.target.value})}/></label><label>Descrizione<textarea rows={4} required minLength={10} value={d.description} onChange={e=>setD({...d,description:e.target.value})}/></label><div className="two-col"><label>Categoria<input disabled={!admin} required value={d.category} onChange={e=>setD({...d,category:e.target.value})}/></label><label>Luogo<input required value={d.location} onChange={e=>setD({...d,location:e.target.value})}/></label></div><div className="two-col"><label>Contributo per incontro (€)<input type="number" min="0" step="0.01" disabled={!admin} value={d.price} onChange={e=>setD({...d,price:Number(e.target.value)})}/></label><label>Contributo intero ciclo (€)<input type="number" min="0" step="0.01" disabled={!admin||occurrences.length<2} value={d.cycle} onChange={e=>setD({...d,cycle:Number(e.target.value)})}/></label></div>{occurrences.map((o,i)=><fieldset key={o.id}><legend>Incontro {i+1}</legend><p className="small muted">Date e orari in UTC. Il calendario pubblico li mostra nel fuso di Roma.</p><div className="two-col"><label>Inizio (UTC)<input required type="datetime-local" value={o.startsAt.slice(0,16)} onChange={e=>{if(e.target.value)setOccurrences(os=>os.map((x,n)=>n===i?{...x,startsAt:new Date(e.target.value+'Z').toISOString()}:x))}}/></label><label>Fine (UTC)<input required type="datetime-local" value={o.endsAt.slice(0,16)} onChange={e=>{if(e.target.value)setOccurrences(os=>os.map((x,n)=>n===i?{...x,endsAt:new Date(e.target.value+'Z').toISOString()}:x))}}/></label><label>Capienza<input required type="number" min="0" value={o.capacity} onChange={e=>setOccurrences(os=>os.map((x,n)=>n===i?{...x,capacity:Number(e.target.value)}:x))}/></label><label>Prenotazioni entro (UTC)<input required type="datetime-local" value={o.bookingDeadline.slice(0,16)} onChange={e=>{if(e.target.value)setOccurrences(os=>os.map((x,n)=>n===i?{...x,bookingDeadline:new Date(e.target.value+'Z').toISOString()}:x))}}/></label><label>Annullamenti entro (UTC)<input required type="datetime-local" value={o.cancellationDeadline.slice(0,16)} onChange={e=>{if(e.target.value)setOccurrences(os=>os.map((x,n)=>n===i?{...x,cancellationDeadline:new Date(e.target.value+'Z').toISOString()}:x))}}/></label></div></fieldset>)}{admin&&<button type="button" className="text-link" onClick={()=>{const o=occurrences[occurrences.length-1];const plus=(x:string)=>new Date(Date.parse(x)+7*86400000).toISOString();setOccurrences([...occurrences,{...o,id:uuid(),startsAt:plus(o.startsAt),endsAt:plus(o.endsAt),bookingDeadline:plus(o.bookingDeadline),cancellationDeadline:plus(o.cancellationDeadline)}])}}><Plus size={17}/>Aggiungi incontro dopo una settimana</button>}{admin&&<><div className="two-col"><label>Stato<select value={d.status} onChange={e=>setD({...d,status:e.target.value as Activity['status']})}>{['draft','published','cancelled','concluded'].map(v=><option key={v} value={v}>{statusText[v]}</option>)}</select></label><label>Responsabile<select value={d.manager} onChange={e=>setD({...d,manager:e.target.value})}><option value="">Da assegnare</option>{accounts.filter(a=>a.role!=='user').map(a=><option key={a.id} value={a.id}>{a.name} {a.surname}</option>)}</select></label><label>Rimborso nei termini (%)<input type="number" min="0" max="100" value={d.refund} onChange={e=>setD({...d,refund:Number(e.target.value)})}/></label><label>Stile copertina<select value={d.cover} onChange={e=>setD({...d,cover:e.target.value as Activity['cover']})}><option value="music">Musica</option><option value="art">Fotografia</option><option value="words">Parole</option><option value="lab">Laboratorio</option></select></label></div><label className="check-label"><input type="checkbox" checked={d.onsite} onChange={e=>setD({...d,onsite:e.target.checked})}/>Pagamento sul posto</label><label className="check-label"><input type="checkbox" checked={d.online} onChange={e=>setD({...d,online:e.target.checked})}/>Pagamento online (richiede provider configurato)</label></>}<p className="notice">Le variazioni alle attività con prenotazioni generano comunicazioni ai partecipanti. I prezzi già acquisiti non vengono modificati.</p><button className="button wide" disabled={busy}>Salva attività<Check size={18}/></button></form>}
function MembershipForm({settings,busy,onSave}:{settings:any;busy:boolean;onSave:(v:any)=>void}){const [d,setD]=useState({card:'',from:settings?.membershipFrom||'',to:settings?.membershipTo||'',paidCents:settings?.membershipFeeCents||0,approved:false});return <form onSubmit={e=>{e.preventDefault();onSave(d)}}><p>Registrare la tessera soltanto dopo il perfezionamento della procedura associativa. L’incasso della quota da solo non basta.</p><label>Numero tessera<input required value={d.card} onChange={e=>setD({...d,card:e.target.value})}/></label><div className="two-col"><label>Valida dal<input type="date" required value={d.from} onChange={e=>setD({...d,from:e.target.value})}/></label><label>Valida al<input type="date" required value={d.to} onChange={e=>setD({...d,to:e.target.value})}/></label></div><label>Quota incassata (€)<input required type="number" step="0.01" min="0" value={d.paidCents/100} onChange={e=>setD({...d,paidCents:Math.round(Number(e.target.value)*100)})}/></label><label className="check-label"><input required type="checkbox" checked={d.approved} onChange={e=>setD({...d,approved:e.target.checked})}/><span>Confermo l’ammissione perfezionata secondo statuto e la mia autorizzazione a registrarla.</span></label><button className="button wide" disabled={busy}>Registra tessera e quota</button></form>}
function SettingsForm({settings,accounts,busy,onSave}:{settings:ClubSettings;accounts:Account[];busy:boolean;onSave:(v:any)=>void}){const [s,setS]=useState(settings);const {staffMfaApproved,...editable}=s;return <form onSubmit={e=>{e.preventDefault();onSave(editable)}}><div className="panel"><h2>I contenuti del sito</h2><label>Frase di apertura<input maxLength={150} value={s.homeText} onChange={e=>setS({...s,homeText:e.target.value})}/></label><label>Chi siamo<textarea rows={4} value={s.about} onChange={e=>setS({...s,about:e.target.value})}/></label><label>Informazioni sul tesseramento<textarea rows={4} value={s.membershipText} onChange={e=>setS({...s,membershipText:e.target.value})}/></label><div className="two-col"><label>Email<input type="email" value={s.contactEmail} onChange={e=>setS({...s,contactEmail:e.target.value})}/></label><label>Telefono<input value={s.phone} onChange={e=>setS({...s,phone:e.target.value})}/></label></div><label>Indirizzo<input value={s.address} onChange={e=>setS({...s,address:e.target.value})}/></label></div><div className="panel top-space"><h2>Regole associative</h2><label>Comportamento lista d’attesa<select value={s.waitPolicy} onChange={e=>setS({...s,waitPolicy:e.target.value as ClubSettings['waitPolicy']})}><option value="unset">Da approvare · nessuna offerta automatica</option><option value="strict">Ordine rigoroso · attendi il primo gruppo</option><option value="fit">Primo gruppo compatibile · conserva gli altri in coda</option></select></label><div className="two-col"><label>Durata offerta (minuti)<input type="number" min="1" max="1440" value={s.waitOfferMinutes} onChange={e=>setS({...s,waitOfferMinutes:Number(e.target.value)})}/></label><label>Quota associativa (€)<input type="number" min="0" step="0.01" value={s.membershipFeeCents===null?'':s.membershipFeeCents/100} onChange={e=>setS({...s,membershipFeeCents:e.target.value===''?null:Math.round(Number(e.target.value)*100)})}/></label><label>Validità dal<input type="date" value={s.membershipFrom} onChange={e=>setS({...s,membershipFrom:e.target.value})}/></label><label>Validità al<input type="date" value={s.membershipTo} onChange={e=>setS({...s,membershipTo:e.target.value})}/></label></div>{[['membershipApproved','Procedura di ammissione e tesseramento validata dal direttivo'],['policyApproved','Condizioni di prenotazione e annullamento approvate'],['onsitePaymentRequired','Saldo contributo obbligatorio prima dell’ingresso']].map(([k,t])=><label className="check-label" key={k}><input type="checkbox" checked={Boolean(s[k as keyof ClubSettings])} onChange={e=>setS({...s,[k]:e.target.checked})}/>{t}</label>)}</div><div className="panel top-space"><h2>Operatori e comunicazioni</h2>{accounts.filter(a=>a.role!=='user').map(a=><div key={a.id}><strong>{a.name} {a.surname}</strong><div className="two-col"><label className="check-label"><input type="checkbox" checked={s.staffRecipients.includes(a.id)} onChange={e=>setS({...s,staffRecipients:e.target.checked?[...s.staffRecipients,a.id]:s.staffRecipients.filter(x=>x!==a.id)})}/>Destinatario avvisi amministrativi</label><label className="check-label"><input type="checkbox" checked={s.onsiteDelegates.includes(a.id)} onChange={e=>setS({...s,onsiteDelegates:e.target.checked?[...s.onsiteDelegates,a.id]:s.onsiteDelegates.filter(x=>x!==a.id)})}/>Delega al tesseramento sul posto</label></div></div>)}</div><div className="panel top-space"><h2>Galleria fotografica</h2><p>Inserisci soltanto fotografie autorizzate, disponibili tramite un URL HTTPS.</p>{(s.gallery||[]).map((img,i)=><div className="two-col" key={i}><label>URL immagine<input type="url" value={img.url} onChange={e=>setS({...s,gallery:s.gallery.map((x,n)=>n===i?{...x,url:e.target.value}:x)})}/></label><label>Descrizione alternativa<input value={img.alt} onChange={e=>setS({...s,gallery:s.gallery.map((x,n)=>n===i?{...x,alt:e.target.value}:x)})}/></label><button type="button" className="text-link danger" onClick={()=>setS({...s,gallery:s.gallery.filter((_,n)=>n!==i)})}>Rimuovi</button></div>)}<button className="text-link" type="button" onClick={()=>setS({...s,gallery:[...(s.gallery||[]),{url:'',alt:''}]})}><Plus size={17}/>Aggiungi fotografia</button></div><button className="button top-space" disabled={busy}>Salva contenuti e regole<Check size={18}/></button></form>}
